steps.command:
cat > /etc/nginx/conf.d/cme-914-cors.conf <<'EOF'
map $http_origin $cors_origin {
    default "";
    "https://<allowed_origin_1>" $http_origin;
    "https://<allowed_origin_2>" $http_origin;
}

map $cors_origin $cors_credentials {
    default "";
    "~.+" "true";
}

